// .opencode/plugins/canal_buzon.js
//
// Canal de recados de Big Pickle (reparado).
//
// Reglas que cumple este programita (las vigila
// vigias/test_vigia_recados_no_se_pierden.py):
//
//   1) La marca de cada recado empieza por "prt_".
//      opencode rechaza la marca vieja "canal-", asi que aqui no aparece
//      ni 'canal-"' ni 'canal-Date' por ningun lado.
//
//   2) Si NO hay sesion abierta, NO se lee y NO se marca:
//      se llama a arnes/canal.py leer con --sin-marcar y se devuelve el
//      recado sin tocarlo. Asi un recado jamas se pierde por leerlo
//      cuando nadie puede recibirlo.
//
//   3) Se marca como leido (argumento "marcar") SOLO despues de entregar
//      el recado a la sesion. Primero se entrega, luego se marca.
//
// No se toca arnes/canal.py: aqui solo se le llama.

const { execFileSync } = require('child_process');
const path = require('path');

// Raiz del proyecto: este archivo vive en .opencode/plugins/, asi que subimos dos niveles.
const RAIZ = path.resolve(__dirname, '..', '..');
const CANAL_PY = path.join(RAIZ, 'arnes', 'canal.py');

// Prefijo de la marca de cada recado. Debe empezar por "prt_".
const PREFIJO_MARCA = 'prt_';

/**
 * Construye la marca de un recado a partir de su identificador.
 * Siempre empieza por "prt_".
 */
function marcaDeRecado(id) {
  return PREFIJO_MARCA + String(id);
}

/**
 * Llama a arnes/canal.py leer.
 *
 * @param {string} buzon  nombre del buzon (p.ej. 'opencode')
 * @param {boolean} marcar  true solo si ya se entrego el recado a la sesion
 * @returns {Array} lista de recados
 */
function leerRecados(buzon, marcar) {
  const args = [CANAL_PY, 'leer', buzon];
  if (marcar) {
    // Marcar como leido: SOLO despues de entregar.
    args.push('marcar');
  } else {
    // Sin sesion abierta no se lee ni se marca: se lee sin marcar.
    args.push('--sin-marcar');
  }
  const salida = execFileSync('python', args, {
    cwd: RAIZ,
    encoding: 'utf-8',
  });
  const texto = (salida || '').trim();
  if (!texto) {
    return [];
  }
  try {
    const datos = JSON.parse(texto);
    return Array.isArray(datos) ? datos : [datos];
  } catch (e) {
    // Si no es JSON, devolvemos las lineas no vacias como recados crudos.
    return texto.split('\n').filter((l) => l.trim().length > 0);
  }
}

/**
 * Entrega un recado a la sesion abierta.
 * Devuelve true si la entrega fue bien.
 *
 * @param {object} sesion  sesion abierta (o null si no hay)
 * @param {object} recado  recado a entregar
 */
function entregarRecado(sesion, recado) {
  if (!sesion) {
    return false;
  }
  if (typeof sesion.entregar === 'function') {
    sesion.entregar(recado);
    return true;
  }
  if (typeof sesion.recibir === 'function') {
    sesion.recibir(recado);
    return true;
  }
  if (typeof sesion.enviar === 'function') {
    sesion.enviar(recado);
    return true;
  }
  // Sin forma conocida de entregar, no damos por entregado.
  return false;
}

/**
 * Ciclo del buzon: lee los recados y los entrega a la sesion.
 *
 * - Si no hay sesion abierta: lee con --sin-marcar y NO marca nada.
 * - Si hay sesion: entrega cada recado y, solo despues de entregarlo,
 *   marca el buzon como leido (argumento "marcar").
 *
 * @param {object|null} sesion  sesion abierta, o null si no hay
 * @param {string} buzon  nombre del buzon (por defecto 'opencode')
 */
function revisarBuzon(sesion, buzon) {
  const nombreBuzon = buzon || 'opencode';

  if (!sesion) {
    // No hay sesion abierta: NO se lee ni se marca.
    // Se llama a leer con --sin-marcar y se devuelve sin tocar nada.
    const recados = leerRecados(nombreBuzon, false);
    return recados.map((r) => ({
      marca: marcaDeRecado(r && r.id !== undefined ? r.id : ''),
      recado: r,
      entregado: false,
    }));
  }

  // Hay sesion: primero se lee sin marcar, para no perder nada si falla la entrega.
  const recados = leerRecados(nombreBuzon, false);
  const resultado = [];

  for (const recado of recados) {
    const entregado = entregarRecado(sesion, recado);
    if (entregado) {
      // Solo despues de entregar se marca como leido.
      leerRecados(nombreBuzon, true);
    }
    resultado.push({
      marca: marcaDeRecado(recado && recado.id !== undefined ? recado.id : ''),
      recado: recado,
      entregado: entregado,
    });
  }

  return resultado;
}

module.exports = {
  PREFIJO_MARCA,
  marcaDeRecado,
  leerRecados,
  entregarRecado,
  revisarBuzon,
};
